using Inventory.Legacy;

namespace Inventory;

/// <summary>Writes point-in-time stock snapshots.</summary>
public sealed class SnapshotWriter
{
    private readonly List<string> _snapshots = new();

    public void Write(StockItem item)
    {
        var line = SnapshotApiV2.Persist(item.Sku, item.OnHand);
        _snapshots.Add(line);
    }

    public int Count => _snapshots.Count;
}
